export enum ExerciseType {
  MULTIPLE_CHOICE = 'MULTIPLE_CHOICE',
  DRAG_AND_DROP = 'DRAG_AND_DROP',
  FILL_IN_BLANK = 'FILL_IN_BLANK',
  CODE_SIMULATOR = 'CODE_SIMULATOR',
  AI_GEN = 'AI_GEN'
}

export interface Exercise {
  id: string;
  type: ExerciseType;
  question: string;
  options?: string[];
  correctAnswer: string | string[];
  explanation?: string;
  hint?: string;
  xp: number;
  initialCode?: string;
