import { GoogleGenAI, Type } from "@google/genai";
import { UserRole, ExerciseType, Exercise } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateAIQuestion = async (role: UserRole, level: number): Promise<Partial<Exercise>> => {
  const prompt = `Create a challenging 1C educational question for a ${role} at level ${level}. 
  Focus on technical details or real-world scenarios. Output strictly JSON.
  Return: { "question": string, "options": string[], "correctAnswer": string, "explanation": string, "xp": number }`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            options: { type: Type.ARRAY, items: { type: Type.STRING } },
            correctAnswer: { type: Type.STRING },
            explanation: { type: Type.STRING },
            xp: { type: Type.NUMBER }
          },
          required: ["question", "options", "correctAnswer", "explanation", "xp"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("AI Generation Error", error);
    return {
      question: "Произошла ошибка при генерации ИИ-вопроса. Какой основной объект используется для хранения данных в 1С?",
      options: ["Справочники", "Константы", "Документы"],
      correctAnswer: "Справочники",
      explanation: "Справочники предназначены для хранения условно-постоянной информации.",
      xp: 20
    };
  }
};

export const checkCodeSolution = async (userCode: string, task: string): Promise<{ isCorrect: boolean; feedback: string }> => {
  const prompt = `As a 1C expert, check this code snippet for the task: "${task}".
  User Code: \`\`\`${userCode}\`\`\`
  Return strictly JSON: { "isCorrect": boolean, "feedback": string }`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isCorrect: { type: Type.BOOLEAN },
            feedback: { type: Type.STRING }
          },
          required: ["isCorrect", "feedback"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (error) {
    return { isCorrect: true, feedback: "Keep going! AI is sleeping." };
  }
};

