import React, { useState, useEffect } from 'react';
import { Exercise, ExerciseType } from '../types';
import { CheckCircle2, XCircle, Info, ChevronRight, GripVertical } from 'lucide-react';

interface ExerciseRendererProps {
  exercise: Exercise;
  onComplete: (isCorrect: boolean, xp: number) => void;
  isAI?: boolean;
}

const ExerciseRenderer: React.FC<ExerciseRendererProps> = ({ exercise, onComplete, isAI }) => {
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [dragItems, setDragItems] = useState<string[]>(exercise.snippets || []);
  const [userCode, setUserCode] = useState(exercise.initialCode || '');
  const [isChecked, setIsChecked] = useState(false);
  const [isCorrect, setIsCorrect] = useState<boolean | null>(null);

  useEffect(() => {
    // Reset state for new exercise
    setSelectedOption(null);
    setDragItems(exercise.snippets || []);
    setUserCode(exercise.initialCode || '');
    setIsChecked(false);
    setIsCorrect(null);
  }, [exercise]);

  const handleCheck = () => {
    let correct = false;
    if (exercise.type === ExerciseType.MULTIPLE_CHOICE || exercise.type === ExerciseType.AI_GEN) {
      correct = selectedOption === exercise.correctAnswer;
    } else if (exercise.type === ExerciseType.DRAG_AND_DROP) {
      correct = JSON.stringify(dragItems) === JSON.stringify(exercise.correctAnswer);
    } else if (exercise.type === ExerciseType.CODE_SIMULATOR) {
      // Basic check or regex for simplified logic
      correct = userCode.toLowerCase().includes('добавить');
    }

    setIsCorrect(correct);
    setIsChecked(true);
  };

  const moveItem = (index: number, direction: 'up' | 'down') => {
    const newItems = [...dragItems];
    const target = direction === 'up' ? index - 1 : index + 1;
    if (target < 0 || target >= newItems.length) return;
    [newItems[index], newItems[target]] = [newItems[target], newItems[index]];
    setDragItems(newItems);
  };

  return (
    <div className="flex flex-col h-full space-y-6">
      <div className="space-y-2">
        {isAI && <span className="text-xs font-bold text-purple-600 bg-purple-50 px-2 py-1 rounded-full border border-purple-200">AI GENERATED TASK</span>}
        <h2 className="text-xl md:text-2xl font-bold text-gray-800 leading-tight">
          {exercise.question}
        </h2>
      </div>

      <div className="flex-grow space-y-3">
        {(exercise.type === ExerciseType.MULTIPLE_CHOICE || exercise.type === ExerciseType.AI_GEN) && (
          <div className="grid grid-cols-1 gap-3">
            {exercise.options?.map((option, idx) => (
              <button
                key={idx}
                disabled={isChecked}
                onClick={() => setSelectedOption(option)}
                className={`w-full p-4 text-left border-2 rounded-xl font-semibold transition-all duration-200 
                  ${selectedOption === option ? 'border-blue-500 bg-blue-50 text-blue-700 shadow-md' : 'border-gray-200 hover:border-blue-300 text-gray-600'}
                  ${isChecked && option === exercise.correctAnswer ? 'border-green-500 bg-green-50' : ''}
                  ${isChecked && selectedOption === option && option !== exercise.correctAnswer ? 'border-red-500 bg-red-50' : ''}
                `}
              >
                <div className="flex items-center">
                  <span className="w-8 h-8 rounded-full border border-gray-300 flex items-center justify-center mr-3 shrink-0">
                    {String.fromCharCode(65 + idx)}
                  </span>
                  {option}
                </div>
              </button>
            ))}
          </div>
        )}

        {exercise.type === ExerciseType.DRAG_AND_DROP && (
          <div className="space-y-2">
            {dragItems.map((item, idx) => (
              <div
                key={idx}
                className="flex items-center bg-gray-50 border-2 border-gray-200 rounded-lg p-3 group"
              >
                <GripVertical className="text-gray-400 mr-2 shrink-0 cursor-grab" />
                <code className="flex-grow text-sm font-mono text-gray-700 break-all">{item}</code>
                {!isChecked && (
                  <div className="flex space-x-1 shrink-0 ml-2">
                    <button onClick={() => moveItem(idx, 'up')} className="p-1 hover:bg-gray-200 rounded">↑</button>
                    <button onClick={() => moveItem(idx, 'down')} className="p-1 hover:bg-gray-200 rounded">↓</button>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        {exercise.type === ExerciseType.CODE_SIMULATOR && (
          <div className="bg-gray-900 rounded-xl p-4 font-mono">
            <textarea
              className="w-full h-48 bg-transparent text-green-400 outline-none resize-none"
              spellCheck={false}
              value={userCode}
              onChange={(e) => setUserCode(e.target.value)}
              placeholder="// Write 1C code here..."
              disabled={isChecked}
            />
          </div>
        )}
      </div>

      <div className="pt-6">
        {isChecked ? (
          <div className={`p-4 rounded-xl mb-4 flex items-start space-x-3 ${isCorrect ? 'bg-green-100 border-green-200 border-2' : 'bg-red-100 border-red-200 border-2'}`}>
            {isCorrect ? (
              <CheckCircle2 className="w-6 h-6 text-green-600 mt-1 shrink-0" />
            ) : (
              <XCircle className="w-6 h-6 text-red-600 mt-1 shrink-0" />
            )}
            <div>
              <p className={`font-bold text-lg ${isCorrect ? 'text-green-800' : 'text-red-800'}`}>
                {isCorrect ? 'Great Job!' : 'Incorrect'}
              </p>
              <p className="text-sm text-gray-700">{exercise.explanation}</p>
            </div>
          </div>
        ) : null}

        {!isChecked ? (
          <button
            onClick={handleCheck}
            disabled={
              (exercise.type === ExerciseType.MULTIPLE_CHOICE && !selectedOption) ||
              (exercise.type === ExerciseType.CODE_SIMULATOR && !userCode)
            }
            className={`w-full py-4 rounded-xl font-extrabold text-white text-lg shadow-lg transform transition-transform active:scale-95
              ${(!selectedOption && exercise.type === ExerciseType.MULTIPLE_CHOICE) ? 'bg-gray-300 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700'}
            `}
          >
            CHECK
          </button>
        ) : (
          <button
            onClick={() => onComplete(isCorrect!, exercise.xp)}
            className={`w-full py-4 rounded-xl font-extrabold text-white text-lg shadow-lg flex items-center justify-center space-x-2
              ${isCorrect ? 'bg-green-600 hover:bg-green-700' : 'bg-red-600 hover:bg-red-700'}
            `}
          >
            <span>CONTINUE</span>
            <ChevronRight className="w-6 h-6" />
          </button>
        )}
      </div>
    </div>
  );
};

export default ExerciseRenderer;

import React, { useState, useEffect } from 'react';
import { Lesson, Exercise, ExerciseType } from '../types';
import ExerciseRenderer from './ExerciseRenderer';
import { generateAIQuestion } from '../services/geminiService';
import { X, Award, Loader2 } from 'lucide-react';

interface LessonScreenProps {
  lesson: Lesson;
  onFinish: (xpEarned: number, coinsEarned: number, heartChange: number) => void;
  onExit: () => void;
}

const LessonScreen: React.FC<LessonScreenProps> = ({ lesson, onFinish, onExit }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [exercises, setExercises] = useState<Exercise[]>(lesson.exercises);
  const [xpTotal, setXpTotal] = useState(0);
  const [coinsTotal, setCoinsTotal] = useState(0);
  const [heartsLost, setHeartsLost] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isLoadingAI, setIsLoadingAI] = useState(false);

  // Narrative view
  const [showNarrative, setShowNarrative] = useState(true);

  const handleExerciseComplete = async (isCorrect: boolean, xp: number) => {
    if (isCorrect) {
      setXpTotal(prev => prev + xp);
      setCoinsTotal(prev => prev + 10);
    } else {
      setHeartsLost(prev => prev + 1);
    }

    const nextIndex = currentIndex + 1;

    // Inject AI question at certain point if not already done
    if (nextIndex === 1 && !exercises.some(e => e.type === ExerciseType.AI_GEN)) {
      setIsLoadingAI(true);
      const aiEx = await generateAIQuestion(lesson.role, lesson.level);
      const newEx: Exercise = {
        id: 'ai-gen-' + Date.now(),
        type: ExerciseType.AI_GEN,
        question: aiEx.question!,
        options: aiEx.options!,
        correctAnswer: aiEx.correctAnswer!,
        explanation: aiEx.explanation!,
        xp: aiEx.xp || 50
      };
      setExercises(prev => [...prev.slice(0, nextIndex), newEx, ...prev.slice(nextIndex)]);
      setIsLoadingAI(false);
    }

    if (nextIndex >= exercises.length) {
      setIsFinished(true);
    } else {
      setCurrentIndex(nextIndex);
    }
  };

  if (showNarrative) {
    return (
      <div className="fixed inset-0 bg-white z-[60] flex flex-col p-6 items-center justify-center text-center space-y-6">
        <div className="w-24 h-24 bg-yellow-100 rounded-full flex items-center justify-center">
          <Award className="w-12 h-12 text-yellow-600" />
        </div>
        <h1 className="text-3xl font-extrabold text-gray-900">{lesson.title}</h1>
        <p className="text-xl text-gray-600 italic">"{lesson.narrative}"</p>
        <button
          onClick={() => setShowNarrative(false)}
          className="w-full max-w-xs py-4 bg-blue-600 text-white rounded-xl font-bold text-xl shadow-lg hover:bg-blue-700 transition-colors"
        >
          LET'S GO!
        </button>
      </div>
    );
  }

  if (isFinished) {
    return (
      <div className="fixed inset-0 bg-white z-[60] flex flex-col p-6 items-center justify-center text-center space-y-8 animate-in fade-in zoom-in duration-300">
        <div className="space-y-2">
          <h2 className="text-4xl font-black text-gray-900">LESSON COMPLETE!</h2>
          <p className="text-gray-500 font-bold">You are mastering 1C like a pro.</p>
        </div>

        <div className="grid grid-cols-2 gap-4 w-full max-w-md">
          <div className="bg-blue-50 border-2 border-blue-200 p-6 rounded-2xl flex flex-col items-center">
            <span className="text-blue-600 font-black text-3xl">+{xpTotal}</span>
            <span className="text-blue-400 font-bold text-sm uppercase">Total XP</span>
          </div>
          <div className="bg-yellow-50 border-2 border-yellow-200 p-6 rounded-2xl flex flex-col items-center">
            <span className="text-yellow-600 font-black text-3xl">+{coinsTotal}</span>
            <span className="text-yellow-400 font-bold text-sm uppercase">Coins</span>
          </div>
        </div>

        <button
          onClick={() => onFinish(xpTotal, coinsTotal, -heartsLost)}
          className="w-full max-w-xs py-4 bg-green-600 text-white rounded-xl font-bold text-xl shadow-lg hover:bg-green-700"
        >
          FINISH
        </button>
      </div>
    );
  }

  const progress = (currentIndex / exercises.length) * 100;

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col">
      <div className="p-4 flex items-center space-x-4">
        <button onClick={onExit} className="text-gray-400 hover:text-gray-600 transition-colors">
          <X className="w-8 h-8" />
        </button>
        <div className="flex-grow bg-gray-200 h-4 rounded-full overflow-hidden">
          <div 
            className="bg-green-500 h-full transition-all duration-500 ease-out shadow-sm"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      <div className="flex-grow overflow-y-auto px-4 py-2 md:px-8 max-w-2xl mx-auto w-full">
        {isLoadingAI ? (
          <div className="h-full flex flex-col items-center justify-center space-y-4">
            <Loader2 className="w-12 h-12 text-blue-500 animate-spin" />
            <p className="text-lg font-bold text-gray-500">NoteBookLM is generating your next challenge...</p>
          </div>
        ) : (
          <ExerciseRenderer 
            exercise={exercises[currentIndex]} 
            onComplete={handleExerciseComplete}
            isAI={exercises[currentIndex].type === ExerciseType.AI_GEN}
          />
        )}
      </div>
    </div>
  );
};

export default LessonScreen;

