      {/* Fullscreen Lesson Overlay */}
      {activeLesson && (
        <LessonScreen 
          lesson={activeLesson} 
          onFinish={handleLessonFinish}
          onExit={() => setActiveLesson(null)}
        />
      )}
    </div>
  );
};

