import React, { useState, useEffect, useRef } from 'react';
import { Lesson, Exercise, ExerciseType } from '../types';
import ExerciseRenderer from './ExerciseRenderer';
import { generateAIQuestion } from '../services/geminiService';
import { X, Award, Loader2, Sparkles } from 'lucide-react';

interface LessonScreenProps {
  lesson: Lesson;
  onFinish: (xpEarned: number, coinsEarned: number, heartChange: number) => void;
  onExit: () => void;
}

const LessonScreen: React.FC<LessonScreenProps> = ({ lesson, onFinish, onExit }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [exercises, setExercises] = useState<Exercise[]>(lesson.exercises);
  const [xpTotal, setXpTotal] = useState(0);
  const [coinsTotal, setCoinsTotal] = useState(0);
  const [heartsLost, setHeartsLost] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isLoadingAI, setIsLoadingAI] = useState(false);
  const [showNarrative, setShowNarrative] = useState(true);

  const staticCount = lesson.exercises.length;
  const targetAICount = Math.max(1, Math.ceil(staticCount * 0.3 / 0.7));

  const handleExerciseComplete = async (isCorrect: boolean, xp: number) => {
    if (isCorrect) {
      setXpTotal(prev => prev + xp);
      setCoinsTotal(prev => prev + 10);
    } else {
      setHeartsLost(prev => prev + 1);
    }

    const nextIndex = currentIndex + 1;
    const currentAICount = exercises.filter(e => e.type === ExerciseType.AI_GEN).length;

    if (currentAICount < targetAICount && (nextIndex % 2 === 1 || nextIndex >= exercises.length)) {
      setIsLoadingAI(true);
      try {
        const aiEx = await generateAIQuestion(lesson.role, lesson.level);
        const newEx: Exercise = {
          id: 'ai-gen-' + Date.now(),
          type: ExerciseType.AI_GEN,
          question: aiEx.question || "Новый вопрос от платформы",
          options: aiEx.options || [],
          correctAnswer: aiEx.correctAnswer || "",
          explanation: aiEx.explanation || "",
          xp: aiEx.xp || 50
        };

        const updatedExercises = [...exercises];
        updatedExercises.splice(nextIndex, 0, newEx);
        setExercises(updatedExercises);
      } catch (e) {
        console.error("AI Gen error", e);
      } finally {
        setIsLoadingAI(false);
      }
    }

    if (nextIndex >= exercises.length && !isLoadingAI) {
      setIsFinished(true);
    } else if (!isLoadingAI) {
      setCurrentIndex(nextIndex);
    }
  };

  if (showNarrative) {
    return (
      <div className="fixed inset-0 bg-white z-[60] flex flex-col p-6 items-center justify-center text-center space-y-6">
        <div className="w-20 h-20 bg-yellow-100 rounded-2xl flex items-center justify-center border-2 border-[#FFD200]">
          <Award className="w-10 h-10 text-yellow-600" />
        </div>
        <h1 className="text-3xl font-black text-gray-900">{lesson.title}</h1>
        <p className="text-lg text-gray-600 font-bold max-w-sm">"{lesson.narrative}"</p>
        <div className="bg-purple-50 p-4 rounded-2xl border border-purple-100 flex items-center space-x-3 text-purple-700">
          <Sparkles className="w-5 h-5" />
          <span className="text-xs font-black uppercase">Урок усилен ИИ-сценариями</span>
        </div>
        <button
          onClick={() => setShowNarrative(false)}
          className="w-full max-w-xs py-4 bg-[#FFD200] text-black rounded-2xl font-black text-xl shadow-md hover:brightness-95 transition-all"
        >
          ПОЕХАЛИ!
        </button>
      </div>
    );
  }

  if (isFinished) {
    return (
      <div className="fixed inset-0 bg-white z-[60] flex flex-col p-6 items-center justify-center text-center space-y-8 animate-in fade-in zoom-in duration-300">
        <div className="space-y-2">
          <h2 className="text-4xl font-black text-gray-900 leading-tight">УРОК ЗАВЕРШЕН!</h2>
          <p className="text-gray-500 font-bold">Ты на шаг ближе к статусу Специалиста 1С.</p>
        </div>

        <div className="grid grid-cols-2 gap-4 w-full max-w-md">
          <div className="bg-white border-2 border-gray-100 p-6 rounded-3xl flex flex-col items-center shadow-sm">
            <span className="text-[#CC0000] font-black text-3xl">+{xpTotal}</span>
            <span className="text-gray-400 font-black text-[10px] uppercase mt-1">Опыт (XP)</span>
          </div>
          <div className="bg-white border-2 border-gray-100 p-6 rounded-3xl flex flex-col items-center shadow-sm">
            <span className="text-yellow-600 font-black text-3xl">+{coinsTotal}</span>
            <span className="text-gray-400 font-black text-[10px] uppercase mt-1">Монеты</span>
          </div>
        </div>

        <button
          onClick={() => onFinish(xpTotal, coinsTotal, -heartsLost)}
          className="w-full max-w-xs py-4 bg-green-600 text-white rounded-2xl font-black text-xl shadow-md hover:bg-green-700 transition-all"
        >
          ГОТОВО
        </button>
      </div>
    );
  }

  const progress = (currentIndex / exercises.length) * 100;

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col">
      <div className="p-4 flex items-center space-x-4">
        <button onClick={onExit} className="text-gray-400 hover:text-gray-600 transition-colors">
          <X className="w-7 h-7" />
        </button>
        <div className="flex-grow bg-gray-100 h-3 rounded-full overflow-hidden">
          <div 
            className="bg-[#FFD200] h-full transition-all duration-500 ease-out"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      <div className="flex-grow overflow-y-auto px-4 py-2 md:px-8 max-w-2xl mx-auto w-full">
        {isLoadingAI ? (
          <div className="h-full flex flex-col items-center justify-center space-y-4">
            <div className="relative">
               <Loader2 className="w-12 h-12 text-[#CC0000] animate-spin" />
               <Sparkles className="absolute -top-1 -right-1 w-5 h-5 text-purple-400 animate-pulse" />
            </div>
            <div className="text-center space-y-1">
              <p className="text-lg font-black text-gray-800">ИИ формирует задачу...</p>
              <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">Анализ тех-документации 1С</p>
            </div>
          </div>
        ) : (
          <ExerciseRenderer 
            exercise={exercises[currentIndex]} 
            onComplete={handleExerciseComplete}
            isAI={exercises[currentIndex].type === ExerciseType.AI_GEN}
          />
        )}
      </div>
    </div>
  );
};

