import React, { useState, useEffect } from 'react';
import { Exercise, ExerciseType } from '../types';
import { CheckCircle2, XCircle, ChevronRight, GripVertical } from 'lucide-react';

interface ExerciseRendererProps {
  exercise: Exercise;
  onComplete: (isCorrect: boolean, xp: number) => void;
  isAI?: boolean;
}

const ExerciseRenderer: React.FC<ExerciseRendererProps> = ({ exercise, onComplete, isAI }) => {
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [dragItems, setDragItems] = useState<string[]>(exercise.snippets || []);
  const [userCode, setUserCode] = useState(exercise.initialCode || '');
  const [isChecked, setIsChecked] = useState(false);
  const [isCorrect, setIsCorrect] = useState<boolean | null>(null);

  useEffect(() => {
    setSelectedOption(null);
    setDragItems(exercise.snippets || []);
    setUserCode(exercise.initialCode || '');
    setIsChecked(false);
    setIsCorrect(null);
  }, [exercise]);

  const handleCheck = () => {
    let correct = false;
    if (exercise.type === ExerciseType.MULTIPLE_CHOICE || exercise.type === ExerciseType.AI_GEN) {
      correct = selectedOption === exercise.correctAnswer;
    } else if (exercise.type === ExerciseType.DRAG_AND_DROP) {
      correct = JSON.stringify(dragItems) === JSON.stringify(exercise.correctAnswer);
    } else if (exercise.type === ExerciseType.CODE_SIMULATOR) {
      correct = userCode.toLowerCase().includes('добавить');
    }

    setIsCorrect(correct);
    setIsChecked(true);
  };

  const moveItem = (index: number, direction: 'up' | 'down') => {
    const newItems = [...dragItems];
    const target = direction === 'up' ? index - 1 : index + 1;
    if (target < 0 || target >= newItems.length) return;
    [newItems[index], newItems[target]] = [newItems[target], newItems[index]];
    setDragItems(newItems);
  };

  return (
    <div className="flex flex-col h-full space-y-6">
      <div className="space-y-2">
        {isAI && (
          <span className="text-[10px] font-black text-purple-700 bg-purple-50 px-2 py-1 rounded-md border border-purple-100 uppercase tracking-wider">
            Вопрос от ИИ
          </span>
        )}
        <h2 className="text-xl md:text-2xl font-black text-gray-900 leading-tight">
          {exercise.question}
        </h2>
      </div>

      <div className="flex-grow space-y-3">
        {(exercise.type === ExerciseType.MULTIPLE_CHOICE || exercise.type === ExerciseType.AI_GEN) && (
          <div className="grid grid-cols-1 gap-3">
            {exercise.options?.map((option, idx) => (
              <button
                key={idx}
                disabled={isChecked}
                onClick={() => setSelectedOption(option)}
                className={`w-full p-4 text-left border-2 rounded-2xl font-bold transition-all duration-150 
                  ${selectedOption === option ? 'border-[#FFD200] bg-yellow-50 text-black shadow-sm' : 'border-gray-100 hover:border-gray-200 text-gray-700'}
                  ${isChecked && option === exercise.correctAnswer ? 'border-sky-500 bg-sky-50' : ''}
                  ${isChecked && selectedOption === option && option !== exercise.correctAnswer ? 'border-red-500 bg-red-50' : ''}
                `}
              >
                <div className="flex items-center">
                  <span className="w-7 h-7 rounded-md bg-gray-100 flex items-center justify-center mr-3 shrink-0 text-xs text-gray-500">
                    {idx + 1}
                  </span>
                  {option}
                </div>
              </button>
            ))}
          </div>
        )}

        {exercise.type === ExerciseType.DRAG_AND_DROP && (
          <div className="space-y-2">
            {dragItems.map((item, idx) => (
              <div
                key={idx}
                className="flex items-center bg-white border-2 border-gray-100 rounded-xl p-3 shadow-sm"
              >
                <GripVertical className="text-gray-300 mr-2 shrink-0" />
                <code className="flex-grow text-xs font-mono text-gray-800 break-all">{item}</code>
                {!isChecked && (
                  <div className="flex space-x-1 shrink-0 ml-2">
                    <button onClick={() => moveItem(idx, 'up')} className="p-1 hover:bg-gray-100 rounded text-gray-400">↑</button>
                    <button onClick={() => moveItem(idx, 'down')} className="p-1 hover:bg-gray-100 rounded text-gray-400">↓</button>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="pt-6">
        {isChecked && (
          <div className={`p-4 rounded-2xl mb-4 flex items-start space-x-3 border-2 ${isCorrect ? 'bg-sky-50 border-sky-100' : 'bg-red-50 border-red-100'}`}>
            {isCorrect ? (
              <CheckCircle2 className="w-6 h-6 text-sky-600 mt-1 shrink-0" />
            ) : (
              <XCircle className="w-6 h-6 text-red-600 mt-1 shrink-0" />
            )}
            <div>
              <p className={`font-black text-lg ${isCorrect ? 'text-sky-800' : 'text-red-800'}`}>
                {isCorrect ? 'Отлично!' : 'Не совсем...'}
              </p>
              <p className="text-sm text-gray-600 font-bold">{exercise.explanation}</p>
            </div>
          </div>
        )}

        {!isChecked ? (
          <button
            onClick={handleCheck}
            disabled={
              (exercise.type === ExerciseType.MULTIPLE_CHOICE && !selectedOption) ||
              (exercise.type === ExerciseType.CODE_SIMULATOR && !userCode)
            }
            className={`w-full py-4 rounded-2xl font-black text-lg shadow-md transition-all active:scale-[0.98]
              ${(!selectedOption && exercise.type === ExerciseType.MULTIPLE_CHOICE) ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-[#FFD200] text-black hover:brightness-95'}
            `}
          >
            ПРОВЕРИТЬ
          </button>
        ) : (
          <button
            onClick={() => onComplete(isCorrect!, exercise.xp)}
            className={`w-full py-4 rounded-2xl font-black text-white text-lg shadow-md flex items-center justify-center space-x-2 transition-all
              ${isCorrect ? 'bg-sky-600 hover:bg-sky-700' : 'bg-sky-500 hover:brightness-110'}
            `}
          >
            <span>ПРОДОЛЖИТЬ</span>
            <ChevronRight className="w-6 h-6" />
          </button>
        )}
      </div>
    </div>
  );
};

export default ExerciseRenderer;

import React, { useState, useEffect, useRef } from 'react';
import { Lesson, Exercise, ExerciseType } from '../types';
import ExerciseRenderer from './ExerciseRenderer';
import { generateAIQuestion } from '../services/geminiService';
import { OneCLogo } from '../constants';
import { X, Award, Loader2, Sparkles } from 'lucide-react';

interface LessonScreenProps {
  lesson: Lesson;
  aiDifficulty: number;
  onFinish: (xpEarned: number, coinsEarned: number, heartChange: number) => void;
  onExit: () => void;
}

const LessonScreen: React.FC<LessonScreenProps> = ({ lesson, aiDifficulty, onFinish, onExit }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [exercises, setExercises] = useState<Exercise[]>(lesson.exercises);
  const [xpTotal, setXpTotal] = useState(0);
  const [coinsTotal, setCoinsTotal] = useState(0);
  const [heartsLost, setHeartsLost] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isLoadingAI, setIsLoadingAI] = useState(false);
  const [showNarrative, setShowNarrative] = useState(true);

  const staticCount = lesson.exercises.length;
  const targetAICount = Math.max(1, Math.ceil(staticCount * 0.3 / 0.7));

  const handleExerciseComplete = async (isCorrect: boolean, xp: number) => {
    if (isCorrect) {
      setXpTotal(prev => prev + xp);
      setCoinsTotal(prev => prev + 10);
    } else {
      setHeartsLost(prev => prev + 1);
    }

    const nextIndex = currentIndex + 1;
    const currentAICount = exercises.filter(e => e.type === ExerciseType.AI_GEN).length;

    if (currentAICount < targetAICount && (nextIndex % 2 === 1 || nextIndex >= exercises.length)) {
      setIsLoadingAI(true);
      try {
        const aiEx = await generateAIQuestion(lesson.role, lesson.level, aiDifficulty);
        const newEx: Exercise = {
          id: 'ai-gen-' + Date.now(),
          type: ExerciseType.AI_GEN,
          question: aiEx.question || "Новый вопрос от платформы",
          options: aiEx.options || [],
          correctAnswer: aiEx.correctAnswer || "",
          explanation: aiEx.explanation || "",
          xp: aiEx.xp || 50
        };

        const updatedExercises = [...exercises];
        updatedExercises.splice(nextIndex, 0, newEx);
        setExercises(updatedExercises);
      } catch (e) {
        console.error("AI Gen error", e);
      } finally {
        setIsLoadingAI(false);
      }
    }

    if (nextIndex >= exercises.length && !isLoadingAI) {
      setIsFinished(true);
    } else if (!isLoadingAI) {
      setCurrentIndex(nextIndex);
    }
  };

  if (showNarrative) {
    return (
      <div className="fixed inset-0 bg-white z-[60] flex flex-col p-6 items-center justify-center text-center space-y-6">
        <OneCLogo className="w-20 h-20" />
        <h1 className="text-3xl font-black text-gray-900">{lesson.title}</h1>
        <p className="text-lg text-gray-600 font-bold max-w-sm">"{lesson.narrative}"</p>
        <div className="bg-purple-50 p-4 rounded-2xl border border-purple-100 flex items-center space-x-3 text-purple-700">
          <Sparkles className="w-5 h-5" />
          <span className="text-xs font-black uppercase">Урок усилен ИИ (Сложность: {aiDifficulty}/10)</span>
        </div>
        <button
          onClick={() => setShowNarrative(false)}
          className="w-full max-w-xs py-4 bg-[#FFD200] text-black rounded-2xl font-black text-xl shadow-md hover:brightness-95 transition-all"
        >
          ПОЕХАЛИ!
        </button>
      </div>
    );
  }

  if (isFinished) {
    return (
      <div className="fixed inset-0 bg-white z-[60] flex flex-col p-6 items-center justify-center text-center space-y-8 animate-in fade-in zoom-in duration-300">
        <div className="space-y-2">
          <h2 className="text-4xl font-black text-gray-900 leading-tight">УРОК ЗАВЕРШЕН!</h2>
          <p className="text-gray-500 font-bold">Ты на шаг ближе к статусу Специалиста 1С.</p>
        </div>

        <div className="grid grid-cols-2 gap-4 w-full max-w-md">
          <div className="bg-white border-2 border-gray-100 p-6 rounded-3xl flex flex-col items-center shadow-sm">
            <span className="text-sky-600 font-black text-3xl">+{xpTotal}</span>
            <span className="text-gray-400 font-black text-[10px] uppercase mt-1">Опыт (XP)</span>
          </div>
          <div className="bg-white border-2 border-gray-100 p-6 rounded-3xl flex flex-col items-center shadow-sm">
            <span className="text-yellow-600 font-black text-3xl">+{coinsTotal}</span>
            <span className="text-gray-400 font-black text-[10px] uppercase mt-1">Монеты</span>
          </div>
        </div>

        <button
          onClick={() => onFinish(xpTotal, coinsTotal, -heartsLost)}
          className="w-full max-w-xs py-4 bg-sky-600 text-white rounded-2xl font-black text-xl shadow-md hover:bg-sky-700 transition-all"
        >
          ГОТОВО
        </button>
      </div>
    );
  }

  const progress = (currentIndex / exercises.length) * 100;

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col">
      <div className="p-4 flex items-center space-x-4">
        <button onClick={onExit} className="text-gray-400 hover:text-gray-600 transition-colors">
          <X className="w-7 h-7" />
        </button>
        <div className="flex-grow bg-gray-100 h-3 rounded-full overflow-hidden">
          <div 
            className="bg-[#FFD200] h-full transition-all duration-500 ease-out"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      <div className="flex-grow overflow-y-auto px-4 py-2 md:px-8 max-w-2xl mx-auto w-full">
        {isLoadingAI ? (
          <div className="h-full flex flex-col items-center justify-center space-y-4">
            <div className="relative">
               <Loader2 className="w-12 h-12 text-sky-600 animate-spin" />
               <Sparkles className="absolute -top-1 -right-1 w-5 h-5 text-purple-400 animate-pulse" />
            </div>
            <div className="text-center space-y-1">
              <p className="text-lg font-black text-gray-800">ИИ формирует задачу...</p>
              <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">Уровень сложности: {aiDifficulty}/10</p>
            </div>
          </div>
        ) : (
          <ExerciseRenderer 
            exercise={exercises[currentIndex]} 
            onComplete={handleExerciseComplete}
            isAI={exercises[currentIndex].type === ExerciseType.AI_GEN}
          />
        )}
      </div>
    </div>
  );
};

export default LessonScreen;

