import React, { useState } from 'react';
import { Lesson, Exercise, UserRole, ExerciseType } from '../types';
import { Save, Plus, Trash2, Download, Upload, ChevronDown, ChevronUp, Edit3 } from 'lucide-react';

interface AdminPanelProps {
  lessons: Lesson[];
  onUpdateLessons: (updatedLessons: Lesson[]) => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ lessons, onUpdateLessons }) => {
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);

  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(lessons, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "lessons_config.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        onUpdateLessons(json);
        alert('Конфигурация успешно загружена!');
      } catch (err) {
        alert('Ошибка при чтении файла');
      }
    };
    reader.readAsText(file);
  };

  const updateExercise = (lessonId: string, exId: string, field: keyof Exercise, value: any) => {
    const newLessons = lessons.map(l => {
      if (l.id !== lessonId) return l;
      return {
        ...l,
        exercises: l.exercises.map(ex => ex.id === exId ? { ...ex, [field]: value } : ex)
      };
    });
    onUpdateLessons(newLessons);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
        <div>
          <h2 className="text-2xl font-black text-gray-900 uppercase">Управление контентом</h2>
          <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-1">Редактирование базы знаний 1С</p>
        </div>
        <div className="flex gap-2">
          <label className="cursor-pointer flex items-center space-x-2 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-xl font-black text-xs transition-all">
            <Upload className="w-4 h-4" />
            <span>ИМПОРТ</span>
            <input type="file" className="hidden" accept=".json" onChange={handleImport} />
          </label>
          <button 
            onClick={handleExport}
            className="flex items-center space-x-2 px-4 py-2 bg-sky-100 hover:bg-sky-200 text-sky-600 rounded-xl font-black text-xs transition-all"
          >
            <Download className="w-4 h-4" />
            <span>ЭКСПОРТ JSON</span>
          </button>
        </div>
      </div>

      <div className="space-y-4">
        {lessons.map((lesson) => (
          <div key={lesson.id} className="bg-white rounded-3xl border border-gray-100 overflow-hidden shadow-sm">
            <div 
              className="p-5 flex items-center justify-between cursor-pointer hover:bg-gray-50 transition-colors"
              onClick={() => setEditingLessonId(editingLessonId === lesson.id ? null : lesson.id)}
            >
              <div className="flex items-center space-x-4">
                <div className="w-10 h-10 rounded-xl bg-sky-500 flex items-center justify-center text-white">
                  <Edit3 className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="font-black text-gray-900">{lesson.title}</h3>
                  <p className="text-[10px] font-black text-gray-400 uppercase">{lesson.role} • Уровень {lesson.level}</p>
                </div>
              </div>
              {editingLessonId === lesson.id ? <ChevronUp className="text-gray-300" /> : <ChevronDown className="text-gray-300" />}
            </div>

            {editingLessonId === lesson.id && (
              <div className="p-5 border-t border-gray-50 space-y-6 bg-gray-50/50">
                {lesson.exercises.map((ex, idx) => (
                  <div key={ex.id} className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm space-y-4">
                    <div className="flex items-center justify-between">
                      <span className="text-[10px] font-black text-sky-500 uppercase tracking-widest">Упражнение {idx + 1} ({ex.type})</span>
                      <button className="text-red-400 hover:text-red-600 transition-colors">
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>

                    <div className="space-y-3">
                      <div>
                        <label className="text-[9px] font-black text-gray-400 uppercase ml-1">Вопрос</label>
                        <textarea 
                          value={ex.question}
                          onChange={(e) => updateExercise(lesson.id, ex.id, 'question', e.target.value)}
                          className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-medium focus:ring-2 focus:ring-sky-500 outline-none transition-all"
                          rows={2}
                        />
                      </div>

                      {ex.options && (
                        <div>
                          <label className="text-[9px] font-black text-gray-400 uppercase ml-1">Варианты ответов (через точку с запятой)</label>
                          <input 
                            type="text"
                            value={ex.options.join('; ')}
                            onChange={(e) => updateExercise(lesson.id, ex.id, 'options', e.target.value.split(';').map(s => s.trim()))}
                            className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-medium focus:ring-2 focus:ring-sky-500 outline-none transition-all"
                          />
                        </div>
                      )}

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
