                            onChange={(e) => updateExercise(lesson.id, ex.id, 'xp', parseInt(e.target.value))}
                            className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-medium focus:ring-2 focus:ring-sky-500 outline-none transition-all"
                          />
                        </div>
                      </div>

                      <div>
                        <label className="text-[9px] font-black text-gray-400 uppercase ml-1">Пояснение</label>
                        <input 
                          type="text"
                          value={ex.explanation}
                          onChange={(e) => updateExercise(lesson.id, ex.id, 'explanation', e.target.value)}
                          className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-medium focus:ring-2 focus:ring-sky-500 outline-none transition-all"
                        />
                      </div>
                    </div>
                  </div>
                ))}
                <button className="w-full py-3 border-2 border-dashed border-gray-200 rounded-2xl text-gray-400 hover:text-sky-500 hover:border-sky-200 transition-all font-black text-xs flex items-center justify-center space-x-2">
                  <Plus className="w-4 h-4" />
                  <span>ДОБАВИТЬ ВОПРОС</span>
                </button>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

