import { GoogleGenAI, Type } from "@google/genai";
import { UserRole, ExerciseType, Exercise } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateAIQuestion = async (role: UserRole, level: number, difficulty: number = 5, context?: string): Promise<Partial<Exercise>> => {
  const prompt = `You are a world-class 1C:Enterprise platform instructor. 
  Task: Create a unique, high-quality educational question for a ${role} at experience level ${level}.

  ${context ? `Use this Knowledge Base context: "${context}"` : ''}

  Difficulty Level: ${difficulty}/10. 

  Contextual Requirements:
  - Base the question on official 1C:Enterprise documentation standards.
  - Role Focus: ${role === UserRole.DEVELOPER ? 'Coding, metadata objects, queries.' : role === UserRole.ACCOUNTANT ? 'Accounting entries, tax reports.' : 'CRM, sales analytics.'}

  Output Requirements:
  - Format: Strict JSON.
  - Language: Russian.

  JSON Schema: { "question": string, "options": string[], "correctAnswer": string, "explanation": string, "xp": number }`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            options: { type: Type.ARRAY, items: { type: Type.STRING } },
            correctAnswer: { type: Type.STRING },
            explanation: { type: Type.STRING },
            xp: { type: Type.NUMBER }
          },
          required: ["question", "options", "correctAnswer", "explanation", "xp"]
        }
      }
    });

    const jsonStr = response.text?.trim() || '{}';
    return JSON.parse(jsonStr);
  } catch (error) {
    console.error("AI Generation Error", error);
    throw error;
  }
};

export const parseKBToExercises = async (kbText: string, role: UserRole): Promise<Partial<Exercise>[]> => {
  const prompt = `Extract exactly 3 educational exercises from the following technical text about 1C:Enterprise for the role of ${role}.
  Source Text: "${kbText}"

  Return a JSON array of exercises following the schema: { "question": string, "options": string[], "correctAnswer": string, "explanation": string, "xp": number }`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              explanation: { type: Type.STRING },
              xp: { type: Type.NUMBER }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (e) {
    console.error(e);
    return [];
  }
};

import React, { useState } from 'react';
import { Lesson, Exercise, UserRole, ExerciseType, KBItem } from '../types';
import { generateAIQuestion, parseKBToExercises } from '../services/geminiService';
import { Save, Plus, Trash2, Download, Upload, ChevronDown, ChevronUp, Edit3, BookOpen, Sparkles, Loader2, Database } from 'lucide-react';

interface AdminPanelProps {
  lessons: Lesson[];
  onUpdateLessons: (updatedLessons: Lesson[]) => void;
  aiDifficulty: number;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ lessons, onUpdateLessons, aiDifficulty }) => {
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'lessons' | 'kb'>('lessons');
  const [kbItems, setKbItems] = useState<KBItem[]>([]);
  const [newKbText, setNewKbText] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify({ lessons, kbItems }, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "master_config.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const addAIQuestion = async (lesson: Lesson) => {
    setIsProcessing(true);
    try {
      const context = kbItems.length > 0 ? kbItems[0].content : undefined;
      const aiEx = await generateAIQuestion(lesson.role, lesson.level, aiDifficulty, context);
      const newEx: Exercise = {
        id: 'ai-' + Date.now(),
        type: ExerciseType.MULTIPLE_CHOICE,
        question: aiEx.question!,
        options: aiEx.options,
        correctAnswer: aiEx.correctAnswer!,
        explanation: aiEx.explanation,
        xp: aiEx.xp || 50
      };

      const newLessons = lessons.map(l => l.id === lesson.id ? { ...l, exercises: [...l.exercises, newEx] } : l);
      onUpdateLessons(newLessons);
    } catch (e) {
      alert("Ошибка ИИ генерации");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAddKB = async () => {
    if (!newKbText.trim()) return;
    setIsProcessing(true);
    const newItem: KBItem = {
      id: 'kb-' + Date.now(),
      title: 'Источник от ' + new Date().toLocaleDateString(),
      content: newKbText,
      tags: []
    };
    setKbItems([newItem, ...kbItems]);
    setNewKbText('');
    setIsProcessing(false);
  };

  const generateFromKB = async (kbItem: KBItem, role: UserRole) => {
    setIsProcessing(true);
    try {
      const parsed = await parseKBToExercises(kbItem.content, role);
      const newLesson: Lesson = {
        id: 'lesson-' + Date.now(),
        role: role,
        level: 1,
        title: 'Урок на основе БЗ',
        narrative: 'Автоматически сформированный урок из ваших материалов.',
        exercises: parsed.map((p, i) => ({
          id: `ex-kb-${Date.now()}-${i}`,
          type: ExerciseType.MULTIPLE_CHOICE,
          question: p.question!,
          options: p.options,
          correctAnswer: p.correctAnswer!,
          explanation: p.explanation,
          xp: p.xp || 30
        }))
      };
      onUpdateLessons([newLesson, ...lessons]);
      setActiveTab('lessons');
      setEditingLessonId(newLesson.id);
    } catch (e) {
      alert("Ошибка обработки БЗ");
    } finally {
      setIsProcessing(false);
    }
  };

  const updateExercise = (lessonId: string, exId: string, field: keyof Exercise, value: any) => {
    const newLessons = lessons.map(l => {
      if (l.id !== lessonId) return l;
      return {
        ...l,
        exercises: l.exercises.map(ex => ex.id === exId ? { ...ex, [field]: value } : ex)
      };
    });
    onUpdateLessons(newLessons);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
