import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import { UserRole, UserProgress, Lesson } from './types';
import { ROLE_DATA, INITIAL_LESSONS, OneCLogo } from './constants';
import LessonScreen from './components/LessonScreen';
import AdminPanel from './components/AdminPanel';
import { Trophy, Book, Users, ShoppingBag, Settings, ChevronRight, Zap, Crown, Star, Heart, Coins, BrainCircuit, ShieldCheck, Lock } from 'lucide-react';

const App: React.FC = () => {
  const [progress, setProgress] = useState<UserProgress>({
    xp: 1250,
    coins: 450,
    hearts: 5,
    streak: 7,
    level: 5,
    role: UserRole.DEVELOPER,
    aiDifficulty: 5,
    isAdmin: false
  });

  const [lessons, setLessons] = useState<Lesson[]>(INITIAL_LESSONS);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [view, setView] = useState<'home' | 'leaderboard' | 'shop' | 'profile' | 'admin'>('home');

  const handleRoleChange = (role: UserRole) => {
